/* @lc app=leetcode id=4063 lang=kotlin */ class Solution { fun longestSubarray(nums: IntArray, k: Int): Int = nums.indices.maxOf { i -> nums.drop(i).foldIndexed(Triple(0L, HashSet<Long>(), 0)) { idx, (s, st, best), x -> (s + x).let { ns -> st.add(Math.floorMod(2L * x, k.toLong())).let { Triple(ns, st, if (Math.floorMod(ns, k.toLong()) == 0L || Math.floorMod(ns, k.toLong()) in st) maxOf(best, idx + 1) else best) } } }.third } }